-- mod-boss-coins: the Tarnished Undermine Real, Pix Xizzix who trades for it, and who gives it.
-- Generated by tools/build_boss_coins.py from the files in data/: change those and run the
-- tool again, don't edit this file.
--
--   item 90410            Tarnished Undermine Real: bind on pickup, at most 250.
--   itemextendedcost   90411-90416: one row per price. The client has the same rows in its
--                      patch; a price the client doesn't know can't be paid.
--   creature 9503200   Pix Xizzix, in Booty Bay (also her spawn guid, gossip menu and text).
--   creature 9503201-9503204  her pages: vendor lists, never spawned.
--   mod_boss_coins_source  which bosses give coins, and how many.
--
-- This module's ids: item 90410 and ItemExtendedCost 90411-90429; creature entries, the spawn
-- guid, gossip menu and npc_text 9503200-9503299. No stock rows are changed. Idempotent.
-- Undo with data/sql/uninstall/mod_boss_coins_uninstall_world.sql.

-- The coin. Junk to a vendor (no sell price), so it can only be spent.
DELETE FROM `item_template` WHERE `entry` = 90410;

-- The prices, in coins.
DELETE FROM `itemextendedcost_dbc` WHERE `ID` BETWEEN 90411 AND 90429;

-- Pix Xizzix and her pages. The pages are creature entries only so that they can own a vendor
-- list; nothing spawns them.
DELETE FROM `creature` WHERE `guid` = 9503200;
DELETE FROM `creature_template_model` WHERE `CreatureID` BETWEEN 9503200 AND 9503299;
DELETE FROM `creature_template` WHERE `entry` BETWEEN 9503200 AND 9503299;

-- Her greeting, and an option per page. An option opens the page's vendor list (the core
-- takes the list from ActionMenuID). A page with a phase is only offered to a player who
-- has cleared that mod-individual-progression phase.
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 15 AND `SourceGroup` = 9503200;
DELETE FROM `gossip_menu_option` WHERE `MenuID` = 9503200;
DELETE FROM `gossip_menu` WHERE `MenuID` = 9503200;
DELETE FROM `npc_text` WHERE `ID` = 9503200;

-- What she sells. A class's pieces are shown and sold to that class only; the condition
-- is on her own entry (the core asks the creature the player talks to, not the page).
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId` = 23 AND `SourceGroup` = 9503200;
DELETE FROM `npc_vendor` WHERE `entry` BETWEEN 9503200 AND 9503299;
-- the Dungeon Set 1 pieces
-- the Tier 1 pieces
-- the Tier 2 bracers, gloves, belts and boots
-- Molten Core crafting materials and the flask recipes

-- Who gives coins. `map` is the instance; `encounter` is a boss's DungeonEncounter.dbc id,
-- or 0 for every boss of the map that has no row of its own. `coins` 0 switches a row off.
-- The rows below are only added when missing, so your own changes to them stay; the
-- server reads the table at startup.
CREATE TABLE IF NOT EXISTS `mod_boss_coins_source` (
  `map` SMALLINT UNSIGNED NOT NULL,
  `encounter` INT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'DungeonEncounter.dbc id; 0 = every boss of the map',
  `coins` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `comment` VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`map`, `encounter`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='mod-boss-coins: bosses that give coins';
