INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `BroadcastTextID0`, `lang0`, `Probability0`) VALUES
(9503200, 'Looking to trade, $c? I deal in Tarnished Undermine Reals and nothing else.$B$BThe bosses of Blackrock Mountain carry them. So does Onyxia, and so do the ones in Stratholme, Scholomance and Dire Maul. Each of them pays out once a day.$B$BDungeon sets I sell to anybody. What my crews hauled out of the raids I keep for people who finish a job: put Ragnaros down and I\'ll open the Molten Core crates. Do the same to Nefarian and we\'ll talk about Blackwing Lair.', 'Looking to trade, $c? I deal in Tarnished Undermine Reals and nothing else.$B$BThe bosses of Blackrock Mountain carry them. So does Onyxia, and so do the ones in Stratholme, Scholomance and Dire Maul. Each of them pays out once a day.$B$BDungeon sets I sell to anybody. What my crews hauled out of the raids I keep for people who finish a job: put Ragnaros down and I\'ll open the Molten Core crates. Do the same to Nefarian and we\'ll talk about Blackwing Lair.', 0, 0, 1);
